        }
    }
    return new String(znaki);
}

public static void wyswietl(ArrayList<String> tytuly, ArrayList<String> tresci, int szyfr) {
    if (tytuly.size() == 0) {
        System.out.println("Brak notatek.");
    }
    for (int i = 0; i < tytuly.size(); i++) {
        System.out.println("[" + i + "] Tytul: " + tytuly.get(i) + " | Tresc: " + deszyfruj(tresci.get(i), szyfr));
    }
}

public static int szukajLiniowo(ArrayList<String> tytuly, String szukam) {
    for (int i = 0; i < tytuly.size(); i++) {
        if (tytuly.get(i).equals(szukam)) {
            return i;
        }
    }
    return -1;
}

public static void sortujBabelkowo(ArrayList<String> tytuly, ArrayList<String> tresci) {
    int n = tytuly.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 1; j < n - i; j++) {
            if (tytuly.get(j - 1).compareTo(tytuly.get(j)) > 0) {
                String tmp = tytuly.get(j - 1);
                tytuly.set(j - 1, tytuly.get(j));
                tytuly.set(j, tmp);
                String tmp2 = tresci.get(j - 1);
                tresci.set(j - 1, tresci.get(j));
                tresci.set(j, tmp2);
            }
        }
    }
}

public static void main(String[] args) {
    ArrayList<String> tytuly = new ArrayList<>();
    ArrayList<String> tresci = new ArrayList<>();
    Scanner skan = new Scanner(System.in);
    int szyfr = 3;
    int wybor;
    do {
        menu();
        wybor = skan.nextInt();
        skan.nextLine();
        switch (wybor) {
            case 1:
                System.out.println("Podaj tytul:");
                String tytul = skan.nextLine();
                System.out.println("Podaj tresc:");
                String tresc = skan.nextLine();
                tytuly.add(tytul);
                tresci.add(szyfruj(tresc, szyfr));
                System.out.println("Dodano notatke.");
                break;
            case 2:
                wyswietl(tytuly, tresci, szyfr);
                break;
            case 3:
                System.out.println("Podaj szukany tytul:");
                String szukam = skan.nextLine();
                int poz = szukajLiniowo(tytuly, szukam);
                if (poz == -1) {
                    System.out.println("Nie znalazlem notatki o tytule " + szukam);
                } else {
                    System.out.println("[" + poz + "] Tytul: " + tytuly.get(poz) + " | Tresc: " + deszyfruj(tresci.get(poz), szyfr));
                }
                break;
            case 4:
                sortujBabelkowo(tytuly, tresci);
                System.out.println("Posortowano notatki po tytule.");
                break;
            case 0:
                System.out.println("Koniec programu.");
                break;
            default:
                System.out.println("Nie ma takiej opcji.");
        }
    } while (wybor != 0);
}

