public static int szukajWzorca(String text, String wzor) {
    int n = text.length();
    int m = wzor.length();
    for (int i = 0; i < n - m; i++) {
        boolean pasuje = true;
        for (int j = 0; j < m; j++) {
            if (text.charAt(i + j) != wzor.charAt(j)) {
                pasuje = false;
                break;
            }
        }
        if (pasuje) {
            return i;
        }
    }
    return -1;
}

