public static int szukajBinarnie(ArrayList<String> tytuly, String szukam) {
    int p = 0;
    int k = tytuly.size() - 1;
    while (p <= k) {
        int mid = (p + k) / 2;
        int wynik = tytuly.get(mid).compareTo(szukam);
        if (wynik == 0) {
            return mid;
        } else if (wynik < 0) {
            p = mid + 1;
        } else {
            k = mid - 1;
        }
    }
    return -1;
}

