public static void wczytaj(String nazwa, ArrayList<String> tytuly, ArrayList<String> tresci) {
    File plik = new File(nazwa);
    if (!plik.exists()) {
        System.out.println("Brak pliku " + nazwa + " - zaczynamy od pustej listy");
        return;
    }
    try (BufferedReader czytnik = new BufferedReader(new FileReader(plik))) {
        String linia = czytnik.readLine();
        while (linia != null) {
            String[] kawalki = linia.split("|");
            tytuly.add(kawalki[0]);
            tresci.add(kawalki[1]);
            linia = czytnik.readLine();
        }
        System.out.println("Wczytano notatki z " + nazwa + ": " + tytuly.size());
    } catch (IOException e) {
        System.out.println("Nie mozna odczytac pliku " + nazwa);
    }
}

