    int k = tytuly.size() - 1;
    while (p <= k) {
        int mid = (p + k) / 2;
        int wynik = tytuly.get(mid).compareTo(szukam);
        if (wynik == 0) {
            return mid;
        } else if (wynik < 0) {
            p = mid + 1;
        } else {
            k = mid - 1;
        }
    }
    return -1;
}

public static int szukajWzorca(String text, String wzor) {
    int n = text.length();
    int m = wzor.length();
    for (int i = 0; i <= n - m; i++) {
        boolean pasuje = true;
        for (int j = 0; j < m; j++) {
            if (text.charAt(i + j) != wzor.charAt(j)) {
                pasuje = false;
                break;
            }
        }
        if (pasuje) {
            return i;
        }
    }
    return -1;
}

