                System.out.println("Nie ma takiej opcji.");
        }
    } while (wybor != 0);
}

public static void menu() {
    System.out.println("[1] Dodaj nowa notatke");
    System.out.println("[2] Wyswietl wszystkie notatki");
    System.out.println("[3] Wyszukaj po tytule");
    System.out.println("[4] Posortuj notatki");
    System.out.println("[5] Wyszukaj binarnie po tytule");
    System.out.println("[6] Szukaj slowa w tresciach notatek");
    System.out.println("[7] Zapisz notatki do pliku");
    System.out.println("[0] Wyjscie");
}

public static String szyfrujV(String text, String klucz) {
    char[] znaki = text.toCharArray();
    int j = 0;
    for (int i = 0; i < znaki.length; i++) {
        if (znaki[i] >= 'a' && znaki[i] <= 'z') {
            int szyfr = klucz.charAt(j % klucz.length()) - 'a';
            int tmp = znaki[i] - 'a';
            tmp = (tmp + szyfr) % 26;
            znaki[i] = (char) ('a' + tmp);
            j++;
        } else if (znaki[i] >= 'A' && znaki[i] <= 'Z') {
            int szyfr = klucz.charAt(j % klucz.length()) - 'a';
            int tmp = znaki[i] - 'A';
            tmp = (tmp + szyfr) % 26;
            znaki[i] = (char) ('A' + tmp);
            j++;
        }
    }
    return new String(znaki);
}

public static String deszyfrujV(String text, String klucz) {
    char[] znaki = text.toCharArray();
    int j = 0;
    for (int i = 0; i < znaki.length; i++) {
        if (znaki[i] >= 'a' && znaki[i] <= 'z') {
            int szyfr = klucz.charAt(j % klucz.length()) - 'a';
            int tmp = znaki[i] - 'a';
            tmp = (tmp - szyfr + 26) % 26;
            znaki[i] = (char) ('a' + tmp);
            j++;
        } else if (znaki[i] >= 'A' && znaki[i] <= 'Z') {
            int szyfr = klucz.charAt(j % klucz.length()) - 'a';
            int tmp = znaki[i] - 'A';
            tmp = (tmp - szyfr + 26) % 26;
            znaki[i] = (char) ('A' + tmp);
            j++;
        }
    }
    return new String(znaki);
}

public static void wyswietl(ArrayList<String> tytuly, ArrayList<String> tresci, String klucz) {
    if (tytuly.size() == 0) {
        System.out.println("Brak notatek.");
    }
    for (int i = 0; i < tytuly.size(); i++) {
        System.out.println("[" + i + "] Tytul: " + tytuly.get(i) + " | Tresc: " + deszyfrujV(tresci.get(i), klucz));
    }
}

public static int szukajLiniowo(ArrayList<String> tytuly, String szukam) {
    for (int i = 0; i < tytuly.size(); i++) {
        if (tytuly.get(i).equals(szukam)) {
            return i;
        }
    }
    return -1;
}

public static void sortujBabelkowo(ArrayList<String> tytuly, ArrayList<String> tresci) {
    int n = tytuly.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 1; j < n - i; j++) {
            if (tytuly.get(j - 1).compareTo(tytuly.get(j)) > 0) {
                String tmp = tytuly.get(j - 1);
                tytuly.set(j - 1, tytuly.get(j));
                tytuly.set(j, tmp);
                String tmp2 = tresci.get(j - 1);
                tresci.set(j - 1, tresci.get(j));
                tresci.set(j, tmp2);
            }
        }
    }
}

public static int szukajBinarnie(ArrayList<String> tytuly, String szukam) {
    int p = 0;
    int k = tytuly.size() - 1;
    while (p <= k) {
        int mid = (p + k) / 2;
        int wynik = tytuly.get(mid).compareTo(szukam);
        if (wynik == 0) {
            return mid;
        } else if (wynik < 0) {
            p = mid + 1;
        } else {
            k = mid - 1;
        }
    }
    return -1;
}

public static int szukajWzorca(String text, String wzor) {
    int n = text.length();
    int m = wzor.length();
    for (int i = 0; i <= n - m; i++) {
        boolean pasuje = true;
        for (int j = 0; j < m; j++) {
            if (text.charAt(i + j) != wzor.charAt(j)) {
                pasuje = false;
                break;
            }
        }
        if (pasuje) {
            return i;
        }
    }
    return -1;
}

public static void zapisz(ArrayList<String> tytuly, ArrayList<String> tresci, String klucz) {
    try (PrintWriter pw = new PrintWriter("archiwum.txt")) {
        for (int i = 0; i < tytuly.size(); i++) {
            pw.println(tytuly.get(i) + "|" + deszyfrujV(tresci.get(i), klucz));
        }
        System.out.println("Zapisano notatki do archiwum.txt: " + tytuly.size());
    } catch (FileNotFoundException e) {
        System.out.println("Nie mozna zapisac pliku archiwum.txt");
    }
}

public static void wczytaj(String nazwa, ArrayList<String> tytuly, ArrayList<String> tresci) {
    File plik = new File(nazwa);
    if (!plik.exists()) {
        System.out.println("Brak pliku " + nazwa + " - zaczynamy od pustej listy");
        return;
    }
    try (BufferedReader czytnik = new BufferedReader(new FileReader(plik))) {
        String linia = czytnik.readLine();
        while (linia != null) {
            String[] kawalki = linia.split("|");
            tytuly.add(kawalki[0]);
            tresci.add(kawalki[1]);
            linia = czytnik.readLine();
        }
        System.out.println("Wczytano notatki z " + nazwa + ": " + tytuly.size());
    } catch (IOException e) {
        System.out.println("Nie mozna odczytac pliku " + nazwa);
    }
}

public static void main(String[] args) {
    ArrayList<String> tytuly = new ArrayList<>();
    ArrayList<String> tresci = new ArrayList<>();
    Scanner skan = new Scanner(System.in);
    wczytaj("archiwum.txt", tytuly, tresci);
    System.out.println("Podaj klucz:");
    String klucz = skan.nextLine();
    boolean posortowane = false;
    int wybor;
    do {
        menu();
        wybor = skan.nextInt();
        skan.nextLine();
        switch (wybor) {
            case 1:
                System.out.println("Podaj tytul:");
                String tytul = skan.nextLine();
                System.out.println("Podaj tresc:");
                String tresc = skan.nextLine();
                tytuly.add(tytul);
                tresci.add(szyfrujV(tresc, klucz));
                System.out.println("Dodano notatke.");
                break;
            case 2:
                wyswietl(tytuly, tresci, klucz);
                break;
            case 3:
                System.out.println("Podaj szukany tytul:");
                String szukam = skan.nextLine();
                int poz = szukajLiniowo(tytuly, szukam);
                if (poz == -1) {
                    System.out.println("Nie znalazlem notatki o tytule " + szukam);
                } else {
                    System.out.println("[" + poz + "] Tytul: " + tytuly.get(poz) + " | Tresc: " + deszyfrujV(tresci.get(poz), klucz));
                }
                break;
            case 4:
                sortujBabelkowo(tytuly, tresci);
                posortowane = true;
                System.out.println("Posortowano notatki po tytule.");
                break;
            case 5:
                System.out.println("Podaj szukany tytul:");
                String szukamB = skan.nextLine();
                if (!posortowane) {
                    sortujBabelkowo(tytuly, tresci);
                    posortowane = true;
                }
                int pozB = szukajBinarnie(tytuly, szukamB);
                if (pozB == -1) {
                    System.out.println("Nie znalazlem notatki o tytule " + szukamB);
                } else {
                    System.out.println("[" + pozB + "] Tytul: " + tytuly.get(pozB) + " | Tresc: " + deszyfrujV(tresci.get(pozB), klucz));
                }
                break;
            case 6:
                System.out.println("Podaj szukane slowo:");
                String slowo = skan.nextLine();
                int ile = 0;
                for (int i = 0; i < tytuly.size(); i++) {
                    String jawny = deszyfrujV(tresci.get(i), klucz);
                    if (szukajWzorca(jawny, slowo) != -1) {
                        System.out.println("[" + i + "] Tytul: " + tytuly.get(i) + " | Tresc: " + jawny);
                        ile++;
                    }
                }
                if (ile == 0) {
                    System.out.println("Nie znalazlem slowa " + slowo + " w zadnej notatce.");
                }
                break;
            case 7:
                zapisz(tytuly, tresci, klucz);
                break;
            case 0:
                System.out.println("Koniec programu.");
                break;
            default:
                System.out.println("Nie ma takiej opcji.");
        }
    } while (wybor != 0);
}
